namespace ghidra.graph.viewer.edge;



using edu.uci.ics.jung.algorithms.layout;
using edu.uci.ics.jung.graph;
using edu.uci.ics.jung.visualization;
using ghidra.graph.viewer;
using ghidra.graph.viewer;

/**
 * A renderer designed to override default edge rendering to NOT paint emphasizing effects.  We
 * do this because space is limited in the satellite and because this rendering can take excess
 * processing time.
 * @param <V> the vertex type
 * @param <E> the edge type
 */
public class VisualGraphEdgeSatelliteRenderer<V, E> : VisualEdgeRenderer<V, E> where V : VisualVertex where E : VisualEdge<V> {

	private VisualEdgeRenderer<V, E> rendererDelegate;

	public VisualGraphEdgeSatelliteRenderer(VisualEdgeRenderer<V, E> @delegate) {
		this.rendererDelegate = @delegate;
	}

	/* @Override */
	protected bool isInHoveredVertexPath(E e) {
		return false;
	}

	/* @Override */
	protected bool isInFocusedVertexPath(E e) {
		return false;
	}

	/* @Override */
	protected bool isSelected(E e) {
		return false;
	}

	/* @Override */
	protected bool isEmphasiszed(E e) {
		return false;
	}

	/* @Override */
	public Shape getEdgeShape(RenderContext<V, E> rc, Graph<V, E> graph, E e, float x1, float y1,
			float x2, float y2, bool isLoop, Shape vertexShape) {
		return rendererDelegate.getEdgeShape(rc, graph, e, x1, y1, x2, y2, isLoop, vertexShape);
	}

	/* @Override */
	protected Shape getVertexShapeForArrow(RenderContext<V, E> rc, Layout<V, E> layout, V v) {
		// we use the default shape (the full shape) for arrow detection
		return getCompactShape(rc, layout, v);
	}
}
